                "formula": "Subject + used to + Verb(infinitive)",
                "explanation": "Nicola doesn’t travel much these days. She prefers to stay at home. But she used to travel a lot. She used to travel a lot = she travelled a lot in the past, but she doesn’t do this any more.",
