                "formula": "Subject + won’t (= will not) + Verb(base)",
                "explanation": "We use \"won’t\" to say that somebody refuses to do something, or that a machine/thing fails to work.",
                "khmerExplanation": "យើងប្រើ \"won’t\" ដើម្បីបង្ហាញថានរណាម្នាក់បដិសេធមិនព្រមធ្វើអ្វីមួយ ឬសម្ភារ/ម៉ាស៊ីនមិនព្រមដំណើរការ។",
