                "khmerTitle": "Have to (កាតព្វកិច្ចមកពីច្បាប់ ឬបទបញ្ជាខាងក្រៅ)",
                "formula": "Subject + have to / has to + Verb(base)",
                "explanation": "We use \"have to\" when something is required by rules, laws, or circumstances (external obligation). Somebody else made the decision.",
                "khmerExplanation": "យើងប្រើ \"have to\" នៅពេលដែលកាតព្វកិច្ចនោះកើតឡើងដោយសារច្បាប់ បទបញ្ជាក្រុមហ៊ុន ឬកាលៈទេសៈបង្ខំពីខាងក្រៅ (មិនមែនមកពីចិត្តយើងចង់ទេ)។",
