                "formula": "Subject + must + Verb(base)",
                "explanation": "We use \"must\" when the obligation comes from the speaker’s own personal opinion or feeling, or for urgent personal reminders.",
                "khmerExplanation": "យើងប្រើ \"must\" នៅពេលដែលកាតព្វកិច្ចនោះកើតចេញពីឆន្ទៈ ឬអារម្មណ៍ផ្ទាល់ខ្លួនរបស់អ្នកនិយាយ ឬជាការដាស់តឿនខ្លួនឯងយ៉ាងបន្ទាន់។",
