                "formula": "Subject + be (am/is/are/was/were/been/being) + Past Participle (V3)",
                "explanation": "The passive is always formed with the appropriate tense of \"be\" + past participle (done, cleaned, built, seen).",
                "khmerExplanation": "ទម្រង់ Passive ត្រូវតែបង្កើតឡើងដោយកិរិយាសព្ទ \"be\" (តាមកាលនីមួយៗ) + Past Participle (V3) ជានិច្ច។",
