                "formula": "Passive Sentence + by + Agent (the person/thing who did it)",
                "explanation": "If you want to say who did the action or what caused it, use \"by\" at the end of the passive sentence.",
                "khmerExplanation": "ប្រសិនបើអ្នកចង់បញ្ជាក់ថា នរណាជាអ្នកធ្វើសកម្មភាពនោះ ឬអ្វីជាមូលហេតុបង្ក ត្រូវប្រើពាក្យ \"by\" (ដោយ...) នៅខាងចុងប្រយោគ Passive។",
