                "formula": "Positive Sentence (+) -> Negative Tag (-) | Negative Sentence (-) -> Positive Tag (+)",
                "explanation": "Question tags are mini-questions at the end of a sentence. A positive sentence takes a negative tag. A negative sentence takes a positive tag.",
