                "explanation": "Notice these special exceptions: after \"I am\", the tag is \"aren’t I?\". After \"Let’s\", the tag is \"shall we?\". After imperatives (orders/requests), the tag is usually \"will you?\" or \"would you?\".",
                "khmerExplanation": "ករណីពិសេសដែលត្រូវចាំ៖ ក្រោយ \"I am\" កន្ទុយគឺ \"aren’t I?\" (មិនមែន amn’t I ទេ)។ ក្រោយ \"Let’s\" កន្ទុយគឺ \"shall we?\"។ ក្រោយប្រយោគបញ្ជា ឬស្នើសុំ កន្ទុយគឺ \"will you?\"។",
